import pandas as pd


def load_hydrological_data(filepath):
    """
    ╨Ч╨░╨│╤А╤Г╨╢╨░╨╡╤В ╤Д╨░╨╣╨╗ ╤Б ╨╜╨╡╤Б╨║╨╛╨╗╤М╨║╨╕╨╝╨╕ ╨│╨╕╨┤╤А╨╛╨┐╨╛╤Б╤В╨░╨╝╨╕.
    ╨Т╨╛╨╖╨▓╤А╨░╤Й╨░╨╡╤В:
    - df_raw: ╨╕╤Б╤Е╨╛╨┤╨╜╤Л╨╣ ╨┤╨░╤В╨░╤Д╤А╨╡╨╣╨╝
