def load_data(self):
    path, _ = QFileDialog.getOpenFileName(self, "╨Ч╨░╨│╤А╤Г╨╖╨╕╤В╤М ╨┤╨░╨╜╨╜╤Л╨╡", "", "Excel (*.xlsx)")
    if not path:
        return
    try:
        df = read_work_sheet(path, ["╨Т╨╜╤Г╤В╤А╨╕╨│╨╛╨┤╨╛╨▓╨╛╨╡ ╤А╨░╤Б╨┐╤А╨╡╨┤╨╡╨╗╨╡╨╜╨╕╨╡"], use_columns=True)
        if df.empty:
            df = pd.read_excel(path, skiprows=2)

        # ╨Э╨╛╤А╨╝╨░╨╗╨╕╨╖╤Г╨╡╨╝ ╨║╨╛╨╗╨╛╨╜╨║╨╕ ╨╝╨╡╤Б╤П╤Ж╨╡╨▓ ╨║ 1-12, ╨╕╨╜╨┤╨╡╨║╤Б тАФ ╨│╨╛╨┤
        month_map = {"I": 1, "II": 2, "III": 3, "IV": 4, "V": 5, "VI": 6,
                     "VII": 7, "VIII": 8, "IX": 9, "X": 10, "XI": 11, "XII": 12,
                     "╨п╨Э╨Т": 1, "╨д╨Х╨Т": 2, "╨Ь╨Р╨а": 3, "╨Р╨Я╨а": 4, "╨Ь╨Р╨Щ": 5, "╨Ш╨о╨Э": 6,
                     "╨Ш╨о╨Ы": 7, "╨Р╨Т╨У": 8, "╨б╨Х╨Э": 9, "╨Ю╨Ъ╨в": 10, "╨Э╨Ю╨п": 11, "╨Ф╨Х╨Ъ": 12}
        renamed = {}
        year_col = None
        for c in df.columns:
            cs = str(c).strip().upper()
            if cs in month_map:
                renamed[c] = month_map[cs]
            elif cs in ["╨У╨Ю╨Ф", "YEAR", "YEARS"]:
                renamed[c] = "╨│╨╛╨┤"
                year_col = c
        df = df.rename(columns=renamed)
        if year_col is None:
            year_col = next((c for c in df.columns if "╨│╨╛╨┤" in str(c).lower() or "year" in str(c).lower()), None)
        if year_col is not None and year_col != "╨│╨╛╨┤":
            df = df.rename(columns={year_col: "╨│╨╛╨┤"})

        month_cols = [m for m in range(1, 13) if m in df.columns]
        if year_col is not None and month_cols:
            df = df[["╨│╨╛╨┤"] + month_cols].copy()
            df["╨│╨╛╨┤"] = pd.to_numeric(df["╨│╨╛╨┤"], errors="coerce")
            df = df.dropna(subset=["╨│╨╛╨┤"]).set_index("╨│╨╛╨┤")
            self.monthly_data = df
        else:
            self.monthly_data = df
        self.result_box.append(f"╨Ч╨░╨│╤А╤Г╨╢╨╡╨╜╨╛: {len(df)} ╤Б╤В╤А╨╛╨║, ╤Б╤В╨╛╨╗╨▒╤Ж╤Л: {list(df.columns)[:6]}...")
    except Exception as e:
        QMessageBox.critical(self, "╨Ю╤И╨╕╨▒╨║╨░", str(e))

