def calculate(self):
    if self.monthly_data is None:
        QMessageBox.warning(self, "╨Т╨╜╨╕╨╝╨░╨╜╨╕╨╡", "╨б╨╜╨░╤З╨░╨╗╨░ ╨╖╨░╨│╤А╤Г╨╖╨╕╤В╨╡ ╨┤╨░╨╜╨╜╤Л╨╡")
        return
    try:
        self.sums_df = calculate_water_year_sums(self.monthly_data, periods=self.periods)
        self.stats = compute_intra_annual_stats(self.sums_df)

        self.table.setRowCount(len(self.stats))
        col_names = {"╤Б╤Г╨╝╨╝╨░_╨│╨╛╨┤": "╨У╨╛╨┤", "╤Б╤Г╨╝╨╝╨░_╨Э╨Ы╨Я": "╨Э╨Ы╨Я", "╤Б╤Г╨╝╨╝╨░_╨Ы╨Я": "╨Ы╨Я", "╤Б╤Г╨╝╨╝╨░_╨Ы╨б": "╨Ы╨б"}
        for i, (key, val) in enumerate(self.stats.items()):
            self.table.setItem(i, 0, QTableWidgetItem(col_names.get(key, key)))
            self.table.setItem(i, 1, QTableWidgetItem(f"{val['mean']:.2f}" if val['mean'] else "тАФ"))
            self.table.setItem(i, 2, QTableWidgetItem(f"{val['Cv']:.4f}" if val['Cv'] else "тАФ"))
            self.table.setItem(i, 3, QTableWidgetItem(f"{val['epsilon']:.2f}" if val['epsilon'] else "тАФ"))

        self.result_box.append("╨а╨░╤Б╤З╤С╤В ╤Б╤Г╨╝╨╝ ╨▓╤Л╨┐╨╛╨╗╨╜╨╡╨╜.")
    except Exception as e:
        QMessageBox.critical(self, "╨Ю╤И╨╕╨▒╨║╨░", str(e))

def choose_model_year(self):
    if self.sums_df is None:
        QMessageBox.warning(self, "╨Т╨╜╨╕╨╝╨░╨╜╨╕╨╡", "╨б╨╜╨░╤З╨░╨╗╨░ ╤А╨░╤Б╤Б╤З╨╕╤В╨░╨╣╤В╨╡ ╤Б╤Г╨╝╨╝╤Л")
        return
    try:
